#include <stdio.h>

int twice(int value) {
  printf("inside:%d\n", value);
  return value * 2;
}

int main(void) {
  int value = 3;
  printf("before:%d\n", value);
  int result = twice(value);
  printf("after:%d\n", result);
  return 0;
}

